func (c *Core) cdlmorningdojistarOpenAndFillInternal(inOpen, inHigh, inLow, inClose []float64, startIdx int32, optInPenetration float64, outBegIdx, outNBElement *int32, outInteger []int32) (*CDLMORNINGDOJISTARStream, error) {
	sp := &CDLMORNINGDOJISTARStream{core: c}
	if retCode := c.cdlmorningdojistarOpenImpl(sp, inOpen, inHigh, inLow, inClose, startIdx, optInPenetration, outBegIdx, outNBElement, outInteger, 1); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(*outBegIdx)
	sp.outRangeCount = int(*outNBElement)
	return sp, nil
}

func (c *Core) cdlmorningdojistarOpenInternal(inOpen, inHigh, inLow, inClose []float64, startIdx int32, optInPenetration float64) (*CDLMORNINGDOJISTARStream, error) {
	sp := &CDLMORNINGDOJISTARStream{core: c}
	var outBegIdx, outNBElement int32
	var sink_outInteger [1]int32
	if retCode := c.cdlmorningdojistarOpenSinkFrame(sp, inOpen, inHigh, inLow, inClose, startIdx, optInPenetration, &outBegIdx, &outNBElement, sink_outInteger[:]); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(outBegIdx)
	sp.outRangeCount = int(outNBElement)
	return sp, nil
}

// CDLMORNINGDOJISTAROpen opens a live [CDLMORNINGDOJISTARStream] on a warm-up
// history, oldest bar first, and returns it with its value at the last history
// bar, the value [Core.CDLMORNINGDOJISTAR] writes there.
//
// inOpen, inHigh, inLow and inClose are the histories, of one length; the
// parameters are those of [Core.CDLMORNINGDOJISTAR].
//
// The error is [InsufficientHistory] for a history of at most
// [Core.CDLMORNINGDOJISTARLookback] bars, [OutOfRangeEndIndex] for one longer
// than [IndexMax]+1 bars, and [BadParam] for a parameter out of range or
// histories of different lengths.
func (c *Core) CDLMORNINGDOJISTAROpen(inOpen, inHigh, inLow, inClose []float64, optInPenetration float64) (*CDLMORNINGDOJISTARStream, int32, error) {
	sp, err := c.cdlmorningdojistarOpenInternal(inOpen, inHigh, inLow, inClose, 0, optInPenetration)
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outInteger, nil
}

// CDLMORNINGDOJISTAROpenAndFill opens a stream as [Core.CDLMORNINGDOJISTAROpen]
// does and also writes the outputs over the whole history, as
// [Core.CDLMORNINGDOJISTAR] writes them for bars 0 through len(inOpen)-1,
// returning that range.
//
// Each output must hold len(inOpen) minus [Core.CDLMORNINGDOJISTARLookback]
// values and share no memory with an input or another output.
//
// The errors are those of [Core.CDLMORNINGDOJISTAROpen], and [BadParam] for an
// output that is empty, too short or sharing memory.
func (c *Core) CDLMORNINGDOJISTAROpenAndFill(inOpen, inHigh, inLow, inClose []float64, optInPenetration float64, outInteger []int32) (*CDLMORNINGDOJISTARStream, OutRange, error) {
	if len(inOpen) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.cdlmorningdojistarLookback(optInPenetration))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inClose) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inOpen)-lookback, 0)
	if len(outInteger) == 0 || len(outInteger) < outLen {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.cdlmorningdojistarOpenAndFillInternal(inOpen, inHigh, inLow, inClose, 0, optInPenetration, &outBegIdx, &outNBElement, outInteger)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
